using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using System.Linq;using System.IO;using System.Text;using EchoProtocol.Echo;using EchoProtocol.Puzzle;using EchoProtocol.Horror;
internal class CommandScript:IRunCommand{
 StringBuilder s=new StringBuilder();int pass,fail;void C(bool b,string m){if(b)pass++;else fail++;s.AppendLine((b?"PASS ":"FAIL ")+m);}
 public void Execute(ExecutionResult r){var all=SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var hub=all.First(t=>t.name=="R1 Clinical Observation Hub").gameObject;bool active=hub.activeSelf;hub.SetActive(true);Physics.SyncTransforms();
 int count=0,miss=0;foreach(var b in new[]{new Vector4(-19.85f,-17.3f,-10.65f,48.05f),new Vector4(-17.3f,-4.95f,-10.65f,-8.35f),new Vector4(-17.3f,-4,44.8f,48f),new Vector4(-4.95f,4.95f,-11.9f,-4.1f),new Vector4(-10.15f,-4.3f,25.2f,30),new Vector4(-8.95f,-4.05f,30.2f,44.55f)})for(float x=b.x;x<b.y;x+=.15f)for(float z=b.z;z<b.w;z+=.15f){count++;if(!Physics.Raycast(new Vector3(x,.08f,z),Vector3.down,.4f,~0,QueryTriggerInteraction.Ignore))miss++;}C(miss==0,"floor support "+count+" samples missing="+miss);
 foreach(var t in all.Where(t=>t.name.StartsWith("R3")&&(t.name.Contains("wall")||t.name.Contains("end")||t.name.Contains("pier")||t.name.Contains("glass")||t.name.Contains("leaf")||t.name.Contains("ceiling")))){var col=t.GetComponent<Collider>();if(col==null||col.isTrigger)continue;var b=col.bounds;int n=0,m=0;int axis=b.size.x<b.size.z?0:2;if(t.name.Contains("ceiling"))axis=1;var normal=axis==0?Vector3.right:axis==1?Vector3.up:Vector3.forward;for(float u=(axis==0?b.min.z:b.min.x)+.03f;u<(axis==0?b.max.z:b.max.x)-.02f;u+=.2f)for(float v=(axis==1?b.min.z:b.min.y)+.03f;v<(axis==1?b.max.z:b.max.y)-.02f;v+=.3f){var p=axis==0?new Vector3(b.min.x-.2f,v,u):axis==1?new Vector3(u,b.min.y-.2f,v):new Vector3(u,v,b.min.z-.2f);n++;if(!col.Raycast(new Ray(p,normal),out var hit,.8f))m++;}C(m==0&&n>0,t.name+" cross-section "+n+" misses="+m);}
 foreach(var c in all.SelectMany(t=>t.GetComponents<MonoBehaviour>()).Where(c=>c!=null&&(c is VS1HubReturnGate||c is VS1RecallAnchor||c is RecombinationRelay||c is VS1RecoveryHubGate||c is VS1StrongEventOne||c is BlindAlignmentRelay||c is ParallelObservationRelay))){var so=new SerializedObject(c);var it=so.GetIterator();while(it.NextVisible(true))if(it.propertyType==SerializedPropertyType.ObjectReference)C(it.objectReferenceValue!=null,c.name+"."+it.propertyPath);}
 var loop=Object.FindFirstObjectByType<LoopController>();var a=new SerializedObject(loop).FindProperty("resetTargets");C(a.arraySize==29,"original 29 reset targets preserved");for(int i=0;i<a.arraySize;i++)C(a.GetArrayElementAtIndex(i).objectReferenceValue is ILoopResettable,"reset target "+i);
 C(all.First(t=>t.name=="R3 single distant curtain residue").GetComponentsInChildren<Collider>(true).Length==0,"residue colliderless behind sealed solid glass");C(all.First(t=>t.name=="VS1 R3 Hub Return").GetComponentsInChildren<AudioSource>(true).Length==0,"R3 contains no audio sources");
 hub.SetActive(active);Physics.SyncTransforms();s.AppendLine("TOTAL passed="+pass+" failed="+fail);File.WriteAllText("/tmp/echo-vs1-r3/geometry.txt",s.ToString());r.Log(s.ToString());}}
